    if ((requested_dipole_a_m2 == NULL) || (field_body_t == NULL) || 
        (per_axis_limit_a_m2 == NULL) || (command == NULL) || (torque_nm == NULL)) {
        return ADCS_E_NULL;
    }

    // 2. Check for non-finite values in input vectors
    if (!adcs_is_finite_vec3(requested_dipole_a_m2) || !adcs_is_finite_vec3(field_body_t)) {
        return ADCS_E_RANGE;
    }

    // 3. Check limits are finite and non-negative
    if ((!isfinite(per_axis_limit_a_m2->x)) || (per_axis_limit_a_m2->x < 0.0) ||
        (!isfinite(per_axis_limit_a_m2->y)) || (per_axis_limit_a_m2->y < 0.0) ||
        (!isfinite(per_axis_limit_a_m2->z)) || (per_axis_limit_a_m2->z < 0.0)) {
        return ADCS_E_RANGE;
    }

    // 4. Initialize outputs to zero (failure outputs are zero / default state)
    command->command = (adcs_vec3_t){0.0, 0.0, 0.0};
    command->saturated_axes = 0U;
    *torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};

    // 5. Clamp X axis and set saturation bit
    {
        double req = requested_dipole_a_m2->x;
        double lim = per_axis_limit_a_m2->x;
        if (fabs(req) > lim) {
            command->command->x = copysign(lim, req);
            command->saturated_axes |= (1u << 0);
        } else {
            command->command->x = req;
        }
    }

    // 6. Clamp Y axis and set saturation bit
    {
        double req = requested_dipole_a_m2->y;
        double lim = per_axis_limit_a_m2->y;
        if (fabs(req) > lim) {
            command->command->y = copysign(lim, req);
            command->saturated_axes |= (1u << 1);
        } else {
            command->command->y = req;
        }
    }

    // 7. Clamp Z axis and set saturation bit
    {
        double req = requested_dipole_a_m2->z;
        double lim = per_axis_limit_a_m2->z;
        if (fabs(req) > lim) {
            command->command->z = copysign(lim, req);
            command->saturated_axes |= (1u << 2);
        } else {
            command->command->z = req;
        }
    }

    // 8. Calculate realized torque: tau = m_limited cross B
    *torque_nm = adcs_vec3_cross(&command->command, field_body_t);

    // 9. Return success
    return ADCS_OK;
}

